(()=>{'use strict';const S=window.ManegeStore,D=window.MANEGE,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dialog,reviewId=null;
const orgOptions=(value='')=>(D.stakeholders||[]).map(s=>`<option value="${esc(s.id)}" ${value===s.id?'selected':''}>${esc(s.name)}</option>`).join('');
function overview(){const st=S.state;return `<section class="manage-overview"><div class="manage-toolbar">${st.admin?`<button class="btn primary" data-manage="stakeholder">+ Stakeholder toevoegen</button><button class="btn" data-manage="talk">+ Transcriptie of gesprek toevoegen</button><button class="btn" data-manage="wish">+ Wens of eis toevoegen</button><button class="btn" data-manage="logout">Uitloggen</button>`:`<button class="btn" data-manage="login">Beheerder inloggen</button>`}</div><p class="small muted" role="status">${!S.configured()?'Beveiligde opslag nog niet gekoppeld. De bestaande onderzoeksinformatie is leesbaar; beheer wordt beschikbaar na koppeling.':st.error?esc(st.error):st.admin?'Beheermodus. Concepten zijn alleen zichtbaar voor beheerders; publiceren vraagt een expliciete keuze.':'Openbare weergave. Alleen bevoegde beheerders kunnen gegevens aanpassen.'}</p><div class="stakeholder-cards">${(D.stakeholders||[]).map(s=>`<article><a href="#wensen?org=${encodeURIComponent(s.name)}"><b>${esc(s.name)}</b><small>${D.wishes.filter(w=>w.org===s.name).length} uitspraken</small></a>${s.role?`<p>${esc(s.role)}</p>`:''}${s.description?`<p>${esc(s.description)}</p>`:''}${st.admin?`<button class="btn" data-manage="stakeholder" data-record="${esc(s.id)}">Bewerken</button>`:''}</article>`).join('')}</div>${st.admin?`<details><summary>Gesprekken en transcripties (${st.talks.length})</summary><div class="talk-list">${st.talks.map(t=>`<article><b>${esc(t.title)}</b><span>${esc(D.stakeholders.find(s=>s.id===t.stakeholder_id)?.name||t.stakeholder_id)} · ${esc(t.date||'Datum onbekend')}</span><button class="btn" data-manage="review" data-record="${esc(t.id)}">Openen en beoordelen</button></article>`).join('')||'<p>Nog geen gesprekken toegevoegd.</p>'}</div></details>`:''}</section>`;}
function controls(w){if(!S.state.admin)return '';const id=w.recordId||w.id,record=S.state.records.find(r=>r.id===id);return `<div class="manage-inline">${record&&!record.published?'<span class="tag">Beheerdersconcept · niet openbaar</span>':''}<button class="btn" data-manage="wish" data-record="${esc(id)}">Wens bewerken / koppelen</button><button class="btn" data-manage="important" data-record="${esc(id)}">${w.priority==='Hoog'?'Extra belangrijk ✓':'Markeer extra belangrijk'}</button><button class="btn" data-manage="delete" data-record="${esc(id)}">Verwijderen</button></div>`;}
function modal(title,body,save){document.getElementById('manage-dialog')?.remove();dialog=document.createElement('dialog');dialog.id='manage-dialog';dialog.innerHTML=`<form><div class="manage-dialog-title"><h2>${esc(title)}</h2><button type="button" class="btn" data-close>Sluiten ×</button></div><div class="manage-error" role="alert"></div>${body}<div class="manage-dialog-actions">${save?'<button class="btn primary" type="submit">Opslaan</button>':''}</div></form>`;document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('change',e=>e.stopPropagation());dialog.addEventListener('input',e=>e.stopPropagation());const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();e.stopPropagation();const b=form.querySelector('[type=submit]');if(b)b.disabled=true;try{await save(new FormData(form));dialog.close();}catch(err){form.querySelector('.manage-error').textContent=err.message;}finally{if(b)b.disabled=false;}};dialog.showModal();return dialog;}
const field=(label,name,value='',required=false,type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
function stakeholder(id){const old=D.stakeholders.find(s=>s.id===id)||{},record=S.state.records.find(r=>r.id===id);modal(id?'Stakeholder bewerken':'Stakeholder toevoegen',field('Naam *','name',old.name,true)+field('Organisatie of rol','role',old.role)+`<label>Korte omschrijving<textarea name="description">${esc(old.description||'')}</textarea></label><label class="checkline"><input name="published" type="checkbox" ${record?.published?'checked':''}> Deze stakeholdergegevens openbaar tonen</label>`,async f=>{await S.save('stakeholder',{name:f.get('name'),role:f.get('role'),description:f.get('description'),aliases:[...new Set([...(old.aliases||[]),...(old.name&&old.name!==f.get('name')?[old.name]:[])])]},id,f.has('published'));});}
function wish(id,proposal=null,talk=null){const old=id?D.wishes.find(w=>(w.recordId||w.id)===id):null,record=S.state.records.find(r=>r.id===id),w=record?.data||old||{},orgIds=w.stakeholders||[D.stakeholders.find(s=>s.name===w.org)?.id||talk?.stakeholder_id],type=w.type||'Wens';
 modal(id?'Wens of eis bewerken':'Wens of eis toevoegen',`<fieldset><legend>Stakeholder(s) *</legend>${D.stakeholders.map(s=>`<label class="checkline"><input type="checkbox" name="org" value="${esc(s.id)}" ${orgIds.includes(s.id)?'checked':''}> ${esc(s.name)}</label>`).join('')}</fieldset>`+field('Omschrijving *','title',w.title||proposal?.text||'',true)+`<label>Type *<select name="type">${[...new Set(['Wens','Eis',type])].map(v=>`<option ${v===type?'selected':''} value="${esc(v)}">${v==='Eis'?'Harde eis':esc(v)}</option>`).join('')}</select></label><div class="manage-grid"><label>Prioriteit<select name="priority">${['Niet vastgesteld','Hoog','Gemiddeld','Laag'].map(v=>`<option ${v===(w.priority||'Niet vastgesteld')?'selected':''}>${v}</option>`).join('')}</select></label><label>Functie voor de Ontwerpstudio<select name="room"><option value="">Nog te bepalen</option>${Object.values(D.rooms).filter(r=>r.id!=='onbekend').map(r=>`<option value="${r.id}" ${w.room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div>`+field('Thema','theme',w.theme||'Ruimtegebruik')+`<label>Groepeer bij vergelijkbare behoefte<select name="group"><option value="">Nieuwe behoefte op omschrijving</option>${[...new Map(D.wishes.map(x=>{const g=window.ManegeResearch.groupOf(x);return[g.id,g];})).values()].map(g=>`<option value="${esc(g.id)}" ${(w.group||old&&window.ManegeResearch.groupOf(old).id)===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><label>Toelichting<textarea name="detail">${esc(w.detail||'')}</textarea></label><label>Gesprek of bron<select name="source"><option value="MANUAL">Handmatig vastgelegd</option>${Object.values(D.sources).filter(s=>s.id!=='MANUAL').map(s=>`<option value="${esc(s.id)}" ${s.id===w.source?'selected':''}>${esc(s.title)}</option>`).join('')}${S.state.talks.map(t=>`<option value="${esc(t.id)}" ${(talk?.id||w.source)===t.id?'selected':''}>${esc(t.title)} (privé)</option>`).join('')}</select></label>`+field('Passage of tijdstip','time',w.time||proposal&&'Tekstpositie '+proposal.start||'')+`<label>Oorspronkelijke passage<textarea name="quote">${esc(w.quote||proposal?.text||'')}</textarea></label><label class="checkline"><input type="checkbox" name="published" ${record?.published?'checked':''}> Ik heb de gegevens en bronpassage gecontroleerd en wil deze openbaar tonen</label><p class="small muted">Zonder dit vinkje blijft de wens een beheerdersconcept. De volledige transcriptie blijft altijd privé.</p>`,async f=>{const data={...w,title:String(f.get('title')).trim(),stakeholders:f.getAll('org'),type:f.get('type'),priority:f.get('priority'),room:f.get('room')||'onbekend',theme:f.get('theme')||'Overig',group:f.get('group')||undefined,detail:f.get('detail'),source:f.get('source'),time:f.get('time')||'Handmatig vastgelegd',quote:f.get('quote'),advice:w.advice||[]};await S.save('wish',data,id,f.has('published'));if(proposal&&talk){await S.updateProposals(talk.id,talk.proposals.map(p=>p.id===proposal.id?{...p,state:'approved'}:p));reviewId=talk.id;}});}
function conversation(){const d=modal('Transcriptie of gesprek toevoegen',`<label>Stakeholder *<select name="stakeholder_id" required><option value="">Kies stakeholder</option>${orgOptions()}</select></label>`+field('Titel *','title','',true)+field('Datum','date','','', 'date')+`<label>Bestand (PDF, DOCX of TXT)<input type="file" name="file" accept=".pdf,.docx,.txt"></label><label>Of plak de gesprekstekst<textarea name="body" rows="9" placeholder="Tekst plakken of typen"></textarea></label><p class="small muted">Maximaal 20 MB. TXT wordt ingelezen. PDF en Word worden veilig als bronbestand opgeslagen; plak daarnaast tekst als je voorstellen wilt laten herkennen. Geen externe AI-dienst: lokale trefwoordherkenning levert alleen voorstellen, nooit automatisch vastgestelde eisen.</p>`,async f=>{const file=f.get('file');reviewId=await S.saveTalk({stakeholder_id:f.get('stakeholder_id'),title:f.get('title'),date:f.get('date')||null,body:f.get('body')},file?.size?file:null);setTimeout(()=>review(reviewId),0);});}
function review(id){const t=S.state.talks.find(t=>t.id===id);if(!t)return;const d=modal(t.title,`<p class="small">Vertrouwelijk gesprek · alleen beheerders</p>${t.file_path?'<button class="btn" type="button" id="talk-download">Bronbestand downloaden</button>':''}<details><summary>Volledige gesprekstekst</summary><pre class="talk-body">${esc(t.body||'Geen tekst geëxtraheerd. Het oorspronkelijke bestand is wel opgeslagen.')}</pre></details><h3>Mogelijke wensen en eisen</h3><p class="small muted">Controleer de context en kies zelf het juiste type. Er is niets automatisch aan de ranglijst toegevoegd.</p>${(t.proposals||[]).map(p=>`<article class="proposal"><p>${esc(p.text)}</p><small>${esc(({pending:'Nog te beoordelen',approved:'Toegevoegd na controle',rejected:'Verworpen'})[p.state]||p.state)}</small>${p.state==='pending'?`<button class="btn" type="button" data-approve="${p.id}">Controleren en toevoegen</button><button class="btn" type="button" data-reject="${p.id}">Verwerpen</button>`:''}</article>`).join('')||'<p>Geen voorstellen herkend. Gebruik Wens of eis toevoegen om zelf een registratie te maken.</p>'}`,null);d.querySelector('#talk-download')?.addEventListener('click',async()=>{try{await S.downloadTalk(t);}catch(e){d.querySelector('.manage-error').textContent=e.message;}});d.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>wish(null,t.proposals.find(p=>p.id===Number(b.dataset.approve)),t));d.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{try{await S.updateProposals(id,t.proposals.map(p=>p.id===Number(b.dataset.reject)?{...p,state:'rejected'}:p));review(id);}catch(e){d.querySelector('.manage-error').textContent=e.message;}});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-manage]');if(!b)return;const action=b.dataset.manage,id=b.dataset.record;if(action==='login'){if(!S.configured()){modal('Beveiligde opslag koppelen','<p>De database is nog niet ingesteld. De installatiehandleiding bevat de eenmalige stappen voor project, beheerder en toegangsregels. Zonder verbinding kunnen hier geen onderzoeksgegevens worden opgeslagen.</p>',null);return;}modal('Beheerder inloggen',field('E-mailadres','email','',true,'email')+field('Wachtwoord','password','',true,'password'),f=>S.login(f.get('email'),f.get('password')));return;}
 if(!S.state.admin)return;if(action==='stakeholder')stakeholder(id);if(action==='wish')wish(id);if(action==='talk')conversation();if(action==='review')review(id);if(action==='logout')await S.logout();if(action==='delete')modal('Wens of eis verwijderen','<p>Deze registratie uit het actieve onderzoeksoverzicht verwijderen? Gekoppelde ontwerpobjecten blijven behouden.</p><label class="checkline"><input type="checkbox" name="confirm" required> Ja, verwijder deze registratie</label>',async()=>S.removeWish(id));if(action==='important'){const w=D.wishes.find(w=>(w.recordId||w.id)===id),r=S.state.records.find(r=>r.id===id);try{await S.save('wish',{...w,stakeholders:r?.data.stakeholders||[D.stakeholders.find(s=>s.name===w.org)?.id||w.org],priority:'Hoog'},id,r?.published||false);}catch(err){modal('Niet opgeslagen','<p>'+esc(err.message)+'</p>',null);}}});
window.ManegeAdmin={overview,controls};
})();
